import { loadRenjunetDB, queryRenjunetPosition, getRenjunetGameMoves } from '@/ai/renjunet'
import { RENJU, STANDARD } from './settings'

export function getBookCategory(gameRule) {
  if (gameRule === RENJU) return 1
  if (gameRule === STANDARD) return 2
  return 0
}

const emptyStats = () => ({
  sideToMove: 1,
  total: 0,
  blackWins: 0,
  draws: 0,
  whiteWins: 0,
  unknown: 0,
  scoreRate: null,
  nextMoves: [],
  games: [],
})

const state = {
  bookMode: false,
  loading: false,
  loadingProgress: 0.0,
  ready: false,
  error: null,
  stats: emptyStats(),
}

const mutations = {
  setBookMode(state, val) {
    state.bookMode = val
  },
  setLoading(state, val) {
    state.loading = val
  },
  setLoadingProgress(state, val) {
    state.loadingProgress = val
  },
  setReady(state, val) {
    state.ready = val
  },
  setError(state, err) {
    state.error = err
  },
  setStats(state, stats) {
    state.stats = stats || emptyStats()
  },
}

const actions = {
  async toggleBookMode({ state, commit, dispatch }) {
    const next = !state.bookMode
    commit('setBookMode', next)
    if (next) {
      await dispatch('queryCurrent')
    }
  },
  async ensureLoaded({ state, commit }) {
    if (state.ready) return true
    commit('setLoading', true)
    commit('setError', null)
    try {
      await loadRenjunetDB((p) => commit('setLoadingProgress', p))
      commit('setLoadingProgress', 1)
      commit('setReady', true)
      return true
    } catch (e) {
      commit('setError', e.message || String(e))
      return false
    } finally {
      commit('setLoading', false)
    }
  },
  async queryCurrent({ state, commit, dispatch, rootState, rootGetters }) {
    if (!state.bookMode) return
    const ok = await dispatch('ensureLoaded')
    if (!ok) return
    const category = getBookCategory(rootGetters['settings/gameRule'])
    if (rootState.position.size !== 15 || rootState.position.blocked.length > 0 || category === 0) {
      commit('setStats', emptyStats())
      return
    }
    const res = queryRenjunetPosition(rootState.position.position, {
      normalizeOrder: rootState.settings.bookNormalizeOrder,
      maxGames: 120,
      category,
    })
    commit('setStats', res)
  },
  loadGame({ rootState, commit, dispatch }, { gameIdx, transform }) {
    const moves = getRenjunetGameMoves(gameIdx, transform)
    if (!moves || moves.length === 0) return
    const curLen = rootState.position.position.length
    commit('position/new', 15, { root: true })
    commit('position/setLastPosition', moves, { root: true })
    for (let i = 0; i < Math.min(curLen + 1, moves.length); i++) {
      dispatch('position/makeMove', moves[i], { root: true })
    }
  },
}

export default {
  namespaced: true,
  state,
  mutations,
  actions,
}
